"""Business-facing homepage content, shared by the page generator and targeted updates."""


def business_sections(icon, checks):
    features = f'''<article class="feature-card large reveal"><div class="feature-icon">{icon('cpu')}</div><h3>Your AI. Your choice.</h3><p>Choose the AI that suits your work and your budget. Use the models included with REACH Plus, or connect a service you already use.</p><div class="model-tokens"><span>More choice</span><span>One workspace</span><span>Your budget</span></div></article>
    <article class="feature-card large reveal"><div class="feature-icon">{icon('folder')}</div><div class="context-graphic" aria-hidden="true"><span></span><span></span><span></span></div><h3>Context stays close.</h3><p>Keep project files and conversations together. Pick up a client proposal or business plan without explaining the whole project again.</p><div class="model-tokens"><span>{icon('file')} Project files</span><span>{icon('chat')} Conversations</span></div></article>
    <article class="feature-card reveal"><div class="feature-icon">{icon('users')}</div><h3>Give every idea a second look.</h3><p>Ask AI assistants to plan, draft, and review from different perspectives. You decide what is ready to use.</p><div class="mini-label"><span class="dot"></span> Your direction. AI support.</div></article>
    <article class="feature-card reveal"><div class="feature-icon">{icon('file')}</div><h3>From blank page to first draft.</h3><p>Turn a brief into a proposal, a customer reply, or website content. Spend more time refining the message and less time getting started.</p><div class="mini-label">Write. Review. Make it yours.</div></article>
    <article class="feature-card reveal"><div class="feature-icon">{icon('chart')}</div><h3>Keep spending in view.</h3><p>Choose a predictable monthly plan, or track spending on your own AI services with Studio’s budget controls.</p><div class="budget-bars" aria-hidden="true">{''.join(f'<i style="--h:{h}%;--delay:-{i*.3}s"></i>' for i,h in enumerate([45,70,56,85,62,100,76,55,82,65,40,70]))}</div></article>'''
    cases = [
        ('chat', 'Sales & customer service', 'Be ready for the next conversation.', 'Draft a proposal, turn your notes into a follow-up, or prepare a clear reply to a customer.', '“Turn these project notes into a client proposal with scope and next steps.”'),
        ('globe', 'Marketing & small business', 'Give your next launch a head start.', 'Develop website copy, product descriptions, and campaign ideas around the business you know best.', '“Draft a landing page for our new service, using this customer brief.”'),
        ('file', 'Operations & everyday work', 'Make the next step clearer.', 'Turn working notes into checklists, first-draft procedures, and summaries you can review and share.', '“Make this process into a checklist a new team member can follow.”'),
    ]
    use_cases = ''.join(f'''<article class="business-case reveal"><div class="feature-icon">{icon(ico)}</div><p class="business-kicker">{label}</p><h3>{title}</h3><p>{description}</p><blockquote>{prompt}</blockquote></article>''' for ico, label, title, description, prompt in cases)
    faq_items = [
        ('What can my business use REACH for?', 'Use REACH to work through ideas, draft customer communications, develop website content, and organize project work. Start with one task, review the result, and build from there.'),
        ('Do I need to be a developer?', 'You can start with an everyday request in the demo, such as drafting a proposal or creating a website. The desktop app brings your project work and AI conversations together. Connection guides and developer tools are available on the <a href="integrations.html">Integrations page</a> when you need them.'),
        ('What does the monthly price include?', 'REACH Subscription Plus is <strong>CAD $25.00 a month, tax included</strong>. It includes unlimited requests to the models supplied on the plan, with no monthly request quota or usage overage. Service limits still apply. Other AI services you connect are billed separately. <a href="subscription.html">See the included models and full plan details</a>.'),
        ('Will REACH replace every subscription I use?', 'That depends on your work. Try the tasks you use other products for, compare the results, and keep any services you still need. The savings estimate only makes sense for subscriptions you can actually replace; it does not assume every product has the same features.'),
        ('What happens to my business information?', 'The AI service you choose receives the request and the information you include. Review its data policies before sharing confidential work. The default website demo uses sample content; the optional live demo sends your request and its project content through your REACH account. <a href="privacy.html">Read the privacy information</a>.'),
        ('How should I get started?', 'Try a familiar business task in the demo, then review the output for accuracy and fit. Install REACH Studio when you are ready to work on your own projects. A 24-hour free trial of the hosted service is available; <a href="subscription.html">check the plan details</a>.'),
    ]
    faq = ''.join(f'<details><summary>{question}{icon("plus")}</summary><p>{answer}</p></details>' for question, answer in faq_items)
    return f'''<section class="section section-line" id="features"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">BUILT AROUND YOUR BUSINESS</div><h2>Less switching.<br><span class="accent">More building.</span></h2></div><a class="text-link" href="platform.html">Explore the platform {icon('arrow')}</a></div><div class="bento">{features}</div></div></section>
    <section class="section section-line" id="business"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">REAL WORK. EVERY DAY.</div><h2>More time for<br><span class="accent">your business.</span></h2></div><p>Start with the work already on your desk. Bring the brief, ask for a first draft, and make it your own.</p></div><div class="business-cases">{use_cases}</div><p class="business-caption">Example tasks you can try. Review AI output before sharing it with customers or using it in your business.</p></div></section>
    <section class="section section-line" id="savings"><div class="container"><div class="section-head reveal"><div><div class="eyebrow">MAKE YOUR AI BUDGET GO FURTHER</div><h2>Fewer subscriptions.<br><span class="accent">More room to grow.</span></h2></div><p>If REACH can cover work you pay for across several AI tools, those monthly costs can add up to real savings.</p></div>
    <div class="business-savings"><article class="plan-card reveal" id="subscription"><p class="plan-kicker">REACH SUBSCRIPTION PLUS</p><p class="plan-price">CAD $25.00<span>/ month</span></p><p>Per subscription. Tax included.</p>{checks(['Unlimited requests to included models','No monthly request quota or usage overage','A workspace for conversations and projects'])}<p class="plan-note">Service limits apply. Other AI services you connect have their own charges.</p><a class="btn btn-primary" href="subscription.html">Explore REACH Plus {icon('arrow')}</a></article>
    <div class="savings-calculator reveal" data-savings-calculator data-reach-monthly="25"><p class="business-kicker">WHAT COULD YOU SAVE?</p><h3>Put your own numbers to work.</h3><p id="savings-assumptions">Illustrative example: replace CAD $60 of monthly AI subscriptions with one REACH Plus subscription. Enter only costs you expect to replace, including tax.</p><div class="savings-inputs"><label for="current-ai-spend">Current AI spend / month (CAD)<input id="current-ai-spend" type="number" inputmode="decimal" min="0" max="1000000" step="0.01" value="60" aria-describedby="savings-assumptions savings-input-error"></label><label for="reach-subscriptions">REACH Plus subscriptions needed<input id="reach-subscriptions" type="number" inputmode="numeric" min="1" max="10000" step="1" value="1" aria-describedby="savings-assumptions savings-input-error"></label></div><p class="savings-input-error" id="savings-input-error" hidden>Enter a monthly cost from 0 to 1,000,000 and a whole number of subscriptions from 1 to 10,000.</p><div class="savings-results" role="status" aria-live="polite" aria-atomic="true"><div><span id="savings-monthly-label">Potential monthly savings</span><strong id="savings-monthly">CAD $35.00</strong></div><div><span id="savings-annual-label">Potential yearly savings</span><strong id="savings-annual">CAD $420.00</strong></div><p id="savings-summary">One REACH Plus subscription costs CAD $25.00/month. That is 58% less than this example’s current spend.</p></div><p class="business-caption">Estimate = current monthly spend − (CAD $25 × subscriptions), multiplied by 12 for a year. Assumes unchanged prices and full replacement of the costs entered. Additional services and setup costs are excluded.</p><noscript><p>The example above is CAD $60 − CAD $25 = CAD $35/month saved. Enable JavaScript to calculate with your own numbers.</p></noscript></div></div>
    <details class="price-comparison"><summary>A published price comparison {icon('plus')}</summary><div class="comparison-content"><h3>Compare monthly subscription prices.</h3><div class="comparison-table-wrap"><table><caption>Canadian prices checked November 14, 2026</caption><thead><tr><th scope="col">Plan</th><th scope="col">Monthly price</th><th scope="col">Billing</th></tr></thead><tbody><tr><th scope="row">REACH Subscription Plus</th><td>CAD $25.00</td><td>Per subscription · tax included</td></tr><tr><th scope="row">Microsoft 365 Copilot Business add-on</th><td>CAD $34.20</td><td>Per user · monthly subscription · plus tax</td></tr></tbody></table></div><p><strong>CAD $9.20 less per month</strong> for one REACH Plus subscription, before adding Microsoft’s applicable tax. That is CAD $110.40 over 12 months at unchanged prices.</p><p>This compares subscription prices, not equivalent features. Copilot includes Microsoft 365 integration and business controls. Its annual offer was CAD $24.43/user/month, paid yearly, plus tax when checked; that base price is below REACH Plus. Your best fit depends on the tools and features you need.</p><a class="text-link" href="https://www.microsoft.com/en-ca/copilot/pricing/business" target="_blank" rel="noopener noreferrer">Check Microsoft’s current prices {icon('external')}<span class="sr-only"> (opens in a new tab)</span></a></div></details></div></section>
    <section class="section section-line" id="business-faq"><div class="container faq-grid"><div class="faq-intro reveal"><div class="eyebrow">BEFORE YOU GET STARTED</div><h2>Good questions.<br>Clear answers.</h2><p>What REACH can do for your work, what it costs, and where to begin.</p><a href="subscription.html" class="text-link">Explore the plan {icon('arrow')}</a></div><div class="faq-list reveal">{faq}</div></div></section>
    <section class="section cta-section"><div class="container"><div class="cta-box reveal"><div><div class="eyebrow">YOUR NEXT TASK, WITHIN REACH</div><h2>Start with your business.</h2><p>Bring one idea. See what you can get done.</p></div><a class="btn btn-primary" href="#workspace">Try the demo {icon('arrow')}</a></div></div></section>'''
